// Illustrative integration sequence, not a standalone SDK program.
require(selectedClientIsNativeCompatible)
require(currentStateAllowsActivation)
// The app adapter drives the selected SDK wrapper and every challenge.
activateWithSelectedClient(clientId, activationUser, activationCode) { result ->
    when (result) {
        is Challenge -> renderRequestedFields(result)
        is Completed -> verifyLocalUserAndDevice()
        is Failed -> showFailureWithoutReissuingCode(result)
    }
}

